insert into public.destinations (id, name, country, blurb, photo, areas, lat, lng, sort_order) values
  ('bali', 'Bali', 'Indonesia', 'Island of temples, cliffside villas and rice terraces. Best from April to October.', 'dest-bali', array['Uluwatu', 'Ubud', 'Seminyak', 'Sidemen']::text[], -8.5, 115.2, 0),
  ('maldives', 'Maldives', 'Maldives', 'Overwater villas on quiet atolls, house reefs and long, slow days. Best from November to April.', 'dest-maldives', array['Noonu Atoll', 'Baa Atoll']::text[], -5.5, 73.2, 1),
  ('santorini', 'Santorini', 'Greece', 'Whitewashed villages on the caldera rim, famous sunsets and volcanic beaches. Best from May to October.', 'dest-santorini', array['Oia', 'Imerovigli']::text[], 36.42, 25.4, 2),
  ('rome', 'Rome', 'Italy', 'Ancient ruins, piazzas and trattorias within walking distance. Best in spring and autumn.', 'dest-rome', array['Centro Storico', 'Trastevere']::text[], 41.9, 12.48, 3),
  ('phuket', 'Phuket', 'Thailand', 'Andaman beaches, island hopping and lively night markets. Best from November to April.', 'hotel-lagoon-bay', array['Kamala', 'Kata']::text[], 7.88, 98.3, 4);
insert into public.hotels (id, destination_id, name, area, address, location_note, description, property_type, rating, review_count, highlights, check_in_time, check_out_time, resort_fee_per_night_cents, tax_rate_bps, lat, lng, is_sample, sort_order) values
  ('grand-horizon', 'bali', 'Grand Horizon Villa & Spa', 'Uluwatu', 'Jl. Pantai Suluban, Uluwatu', '25 min to Ngurah Rai Airport · 10 min to Uluwatu Temple', 'A cliff-top retreat above the Indian Ocean with private pool villas, a sunset spa and an open-air restaurant — 10 minutes from Uluwatu Temple.', 'villa', 4.8, 932, array['Private pool', 'Ocean view']::text[], '14:00', '12:00', 2500, 1000, -8.8291, 115.0849, true, 0),
  ('azure-lagoon', 'maldives', 'The Azure Lagoon Resort', 'Noonu Atoll', 'Manathu Island, Noonu Atoll', '45 min seaplane from Velana Airport · House reef at the villa steps', 'Overwater villas strung along a turquoise lagoon, with glass-floor living rooms, a house reef for snorkelling and dinner on a sandbank.', 'resort', 4.9, 1204, array['Overwater villa', 'Breakfast']::text[], '14:00', '12:00', 4000, 1600, -5.85, 73.35, true, 1),
  ('caldera-cliff', 'santorini', 'Caldera Cliff Suites', 'Oia', 'Nomikos Street, Oia', '5 min walk to Oia Castle · 30 min to Santorini Airport', 'Cave suites carved into the caldera wall, each with a terrace and plunge pool facing the sunset over the volcano.', 'hotel', 4.9, 688, array['Caldera view', 'Plunge pool']::text[], '15:00', '11:00', 0, 1300, 36.4618, 25.3753, true, 2),
  ('palm-courtyard', 'bali', 'Palm Courtyard Hotel', 'Seminyak', 'Jl. Kayu Aya, Seminyak', '5 min walk to Seminyak Beach · 25 min to Ngurah Rai Airport', 'A palm-lined courtyard hotel with a long reflecting pool, a short walk from Seminyak''s beach clubs and boutiques.', 'hotel', 4.7, 1876, array['Breakfast', 'Pool']::text[], '14:00', '12:00', 0, 1000, -8.6913, 115.1682, true, 3),
  ('jungle-mist', 'bali', 'Jungle Mist Retreat', 'Ubud', 'Jl. Raya Sayan, Ubud', '15 min to Ubud Palace · Ayung River valley', 'Pool villas on the edge of the Ayung River gorge, with yoga at sunrise and dinners made from the garden.', 'villa', 4.9, 512, array['Private pool', 'Jungle view']::text[], '14:00', '12:00', 1500, 1000, -8.5069, 115.2625, true, 4),
  ('lagoon-bay', 'phuket', 'Lagoon Bay Resort', 'Kamala', 'Kamala Beach Road, Kamala', 'On Kamala Beach · 35 min to Phuket Airport', 'A beachfront resort around a lagoon pool, with cabanas facing the Andaman Sea and a spa in the gardens.', 'resort', 4.6, 954, array['Beachfront', 'Breakfast']::text[], '15:00', '12:00', 1000, 700, 7.9512, 98.2836, true, 5),
  ('sidemen-valley', 'bali', 'Sidemen Valley Lodge', 'Sidemen', 'Jl. Raya Sidemen, Karangasem', 'Rice-terrace valley · 1 h 45 min to Ngurah Rai Airport', 'A small lodge among rice terraces facing Mount Agung, with an infinity pool and cooking classes.', 'hotel', 4.6, 214, array['Mountain view', 'Breakfast']::text[], '14:00', '11:00', 0, 1000, -8.4728, 115.4417, true, 6),
  ('coral-reef', 'maldives', 'Coral Reef Island Villas', 'Baa Atoll', 'Dhunikolhu Island, Baa Atoll', '35 min seaplane from Velana Airport · UNESCO biosphere reserve', 'Beach villas with decks over the sand, a dive centre on the house reef and a quiet adults'' pool.', 'resort', 4.8, 402, array['Beachfront', 'Private pool']::text[], '14:00', '12:00', 3500, 1600, -5.17, 73.03, true, 7),
  ('imerovigli-sky', 'santorini', 'Imerovigli Sky Houses', 'Imerovigli', 'Main Path, Imerovigli', 'On the caldera path · 20 min walk to Fira', 'Restored captains'' houses with kitchenettes and shared terraces — the quieter side of the caldera, with Oia''s sunset in view.', 'apartment', 4.7, 356, array['Caldera view', 'Kitchenette']::text[], '15:00', '11:00', 0, 1300, 36.4325, 25.4232, true, 8),
  ('kata-palm', 'phuket', 'Kata Palm Hotel', 'Kata', 'Kata Road, Karon', '3 min walk to Kata Beach · 50 min to Phuket Airport', 'A whitewashed hotel around a palm-shaded pool, a short stroll from Kata''s surf beach and night market.', 'hotel', 4.5, 1320, array['Pool', 'Near beach']::text[], '14:00', '12:00', 0, 700, 7.8201, 98.2985, true, 9),
  ('palazzo-aurelia', 'rome', 'Palazzo Aurelia', 'Centro Storico', 'Via dei Coronari, Rome', '4 min walk to Piazza Navona · 10 min to the Pantheon', 'A 17th-century palazzo with frescoed ceilings, a rooftop terrace over the domes and classic rooms on a quiet lane.', 'hotel', 4.7, 1508, array['Historic centre', 'Rooftop']::text[], '14:00', '11:00', 700, 1000, 41.8995, 12.4708, true, 10),
  ('teak-house', 'bali', 'Teak House Beach Club', 'Seminyak', 'Jl. Petitenget, Seminyak', 'On Petitenget Beach · 30 min to Ngurah Rai Airport', 'Teak-roofed bungalows around a sundeck pool, steps from the sand and Seminyak''s sunset bars.', 'resort', 4.5, 768, array['Beachfront', 'Breakfast']::text[], '14:00', '12:00', 1000, 1000, -8.6782, 115.1513, true, 11),
  ('andaman-reflection', 'phuket', 'Andaman Reflection Resort', 'Kamala', 'Kamala Hillside, Kamala', 'Hillside above Kamala Bay · 35 min to Phuket Airport', 'A modern resort built around a mirror-still infinity pool with views over Kamala Bay at dusk.', 'resort', 4.8, 621, array['Infinity pool', 'Sea view']::text[], '15:00', '12:00', 1500, 700, 7.9583, 98.2861, true, 12);
